package agenthub

import("context";"testing";"time";"github.com/example-user/runnerhub/internal/agent";"github.com/example-user/runnerhub/internal/store")
func TestCommandLeaseRedeliversAndAcks(t *testing.T){st,_:=store.OpenSQLite(":memory:");defer st.Close();h,_:=New(st,"1234567890123456","12345678901234567890123456789012");now:=time.Date(2026,8,9,0,0,0,0,time.UTC);h.now=func()time.Time{return now};h.lease=time.Minute;if err:=h.Enqueue("host-1",agent.Command{Type:agent.CommandDelete,WorkerID:"worker-1"});err!=nil{t.Fatal(err)};first:=h.Next("host-1");if len(first)!=1{t.Fatalf("first delivery=%d",len(first))};if got:=h.Next("host-1");len(got)!=0{t.Fatalf("leased command redelivered early: %d",len(got))};now=now.Add(2*time.Minute);again:=h.Next("host-1");if len(again)!=1||again[0].ID!=first[0].ID{t.Fatalf("expected same command after lease expiry: %#v",again)};calls:=0;h.SetResultHandler(func(context.Context,string,agent.CommandResult)error{calls++;return nil});res:=agent.CommandResult{CommandID:first[0].ID,WorkerID:"worker-1",OK:true};if err:=h.HandleResult(context.Background(),"host-1",res);err!=nil{t.Fatal(err)};if err:=h.HandleResult(context.Background(),"host-1",res);err!=nil{t.Fatal(err)};if calls!=1{t.Fatalf("result handler calls=%d",calls)};now=now.Add(2*time.Minute);if got:=h.Next("host-1");len(got)!=0{t.Fatalf("acked command redelivered: %d",len(got))}}
